// Embedded 3D PCB viewer for klepcbgen. Loads the GLB generated by kicad-cli
// into a three.js scene with orbit/zoom/pan controls.
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/GLTFLoader.module.js';
import { OrbitControls } from 'three/addons/OrbitControls.module.js';

let renderer = null;
let scene = null;
let camera = null;
let controls = null;
// The loaded board object (set after GLB load) so view-cube snap can frame it.
let boardObj = null;

const VIEWS = {
  // Board is flat in X-Z, normal along Y. Each entry is a camera position
  // direction (normalized by length) pointing at the target from that view.
  // Y is board thickness; +Y is front face, -Y is back.
  front:   { dir: [0, 1, 0],   label: 'Front' },   // +Y
  back:    { dir: [0, -1, 0],  label: 'Back' },    // -Y
  right:   { dir: [1, 0, 0],   label: 'Right' },   // +X
  left:    { dir: [-1, 0, 0],  label: 'Left' },    // -X
  top:     { dir: [0, 0, 1],   label: 'Top' },     // +Z
  bottom:  { dir: [0, 0, -1],  label: 'Bottom' },  // -Z
  // Iso corners
  frontTopRight:  { dir: [0.65, 0.65, 0.65], label: 'FRT' },
  frontTopLeft:   { dir: [-0.65, 0.65, 0.65], label: 'FLT' },
  backTopRight:   { dir: [0.65, -0.65, 0.65], label: 'BRT' },
  backTopLeft:    { dir: [-0.65, -0.65, 0.65], label: 'BLT' },
};

function normalize(v) {
  const len = Math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2]) || 1;
  return [v[0]/len, v[1]/len, v[2]/len];
}

// Position the ortho camera to look at the board from a given view direction.
// dir is the direction FROM the target TO the camera.
function setView(dir, animate) {
  if (!boardObj || !controls || !camera) return;
  const box = new THREE.Box3().setFromObject(boardObj);
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const maxDim = Math.max(size.x, size.y, size.z) || 1;
  const n = normalize(dir);
  const dist = maxDim * 2.2;

  const target = new THREE.Vector3(center.x, center.y, center.z);
  const pos = new THREE.Vector3(center.x + n[0]*dist,
                                center.y + n[1]*dist,
                                center.z + n[2]*dist);

  // Keep the ortho frustum sized to frame the model.
  const viewHalf = maxDim * 1.7;
  camera.left = -viewHalf;
  camera.right = viewHalf;
  camera.top = viewHalf;
  camera.bottom = -viewHalf;
  camera.updateProjectionMatrix();

  // Snap directly (no animation) for reliability.
  camera.position.copy(pos);
  controls.target.copy(target);
  controls.update();
  renderer.render(scene, camera);
}

function initViewer(canvas) {
  renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(window.devicePixelRatio);
  renderer.outputColorSpace = THREE.SRGBColorSpace;

  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x171a21);

  // Orthographic projection keeps all parallel edges parallel when orbiting,
  // so the board doesn't warp/distort as it rotates.
  const frustum = 2.0;
  camera = new THREE.OrthographicCamera(
    -frustum, frustum, frustum, -frustum, 0.001, 1000
  );
  camera.position.set(1.0, 0.75, 1.2);

  // NOTE: do NOT override camera.up here. The GLB exports the board flat in
  // the X-Z plane with its thickness/normal along Y (KiCad Z-up maps to
  // glTF Y-up). OrbitControls' default +Y up is therefore already correct —
  // forcing a different up (as a previous change did) orbits around an axis
  // that lies IN the board plane and breaks rotation.

  controls = new OrbitControls(camera, canvas);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;

  const hemi = new THREE.HemisphereLight(0xffffff, 0x334155, 0.9);
  scene.add(hemi);
  // Key light from above (top of board).
  const key = new THREE.DirectionalLight(0xffffff, 1.2);
  key.position.set(80, 120, 100);
  scene.add(key);
  // Second key light from below so the underside of the PCB is lit too.
  const keyBottom = new THREE.DirectionalLight(0xffffff, 1.2);
  keyBottom.position.set(-60, -120, -80);
  scene.add(keyBottom);
  const rim = new THREE.DirectionalLight(0x8ab4ff, 0.5);
  rim.position.set(-80, 40, -60);
  scene.add(rim);

  animate();
}

function animate() {
  requestAnimationFrame(animate);
  if (controls) controls.update();
  if (renderer) renderer.render(scene, camera);
}

function fitCamera(obj) {
  const box = new THREE.Box3().setFromObject(obj);
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const maxDim = Math.max(size.x, size.y, size.z) || 1;

  // Position the camera along a fixed diagonal so the board fills the frame.
  const dir = new THREE.Vector3(1, 0.75, 1.2).normalize();
  const dist = maxDim * 2.2;
  camera.position.copy(center).add(dir.multiplyScalar(dist));
  controls.target.copy(center);

  // For an ortho camera, set the frustum half-size to frame the model (this is
  // how ortho "zoom" works — the frustum width controls how much is visible).
  const viewHalf = maxDim * 1.6;
  camera.left = -viewHalf;
  camera.right = viewHalf;
  camera.top = viewHalf;
  camera.bottom = -viewHalf;
  camera.updateProjectionMatrix();
  controls.update();
}

function show3D(url) {
  const preview = document.getElementById('preview');
  const canvas = document.getElementById('pcb3d');
  const placeholder = document.getElementById('placeholder');

  // Clear any previously loaded model.
  if (scene) {
    const toRemove = scene.children.filter(
      (c) => !c.isLight && c.type !== 'Scene' && !(c.isCamera)
    );
    toRemove.forEach((c) => scene.remove(c));
  }

  placeholder.style.display = 'none';
  canvas.style.display = 'block';

  if (!renderer) initViewer(canvas);

  const w = preview.clientWidth || 600;
  const h = preview.clientHeight || 460;
  renderer.setSize(w, h, false);

  new GLTFLoader().load(
    url,
    (gltf) => {
      boardObj = gltf.scene;
      scene.add(gltf.scene);
      fitCamera(gltf.scene);
    },
    undefined,
    (err) => {
      canvas.style.display = 'none';
      placeholder.style.display = 'grid';
      placeholder.innerHTML = '<div class="errorbox">3D preview failed to load.</div>';
    }
  );
}

// Global API for the view cube in the page.
window.__setView = function (key) {
  if (VIEWS[key]) setView(VIEWS[key].dir);
};
window.__viewKeys = Object.keys(VIEWS);

// Called from the page when the 3D canvas is toggled visible again after
// switching to a 2D layer view — re-sync the renderer size to the container.
function setViewerSize() {
  if (!renderer) return;
  const preview = document.getElementById('preview');
  const canvas = document.getElementById('pcb3d');
  const w = preview.clientWidth || 600;
  const h = preview.clientHeight || 460;
  renderer.setSize(w, h, false);
}
window.__setViewerSize = setViewerSize;

window.show3D = show3D;
